def rep(text, old, new, label=""):
    n = text.count(old)
    assert n == 1, f"[{label}] 期望命中 1 次，实际 {n} 次：{old[:80]}"
    return text.replace(old, new, 1)


def cut_between(text, start_mark, end_mark, new, label="", keep_end=True):
    """把 start_mark（含）到 end_mark（按 keep_end 决定含不含）之间整段替换。"""
    a = text.find(start_mark)
    assert a >= 0, f"[{label}] 找不到起点：{start_mark[:60]}"
    assert text.find(start_mark, a + 1) < 0, f"[{label}] 起点不唯一：{start_mark[:60]}"
    b = text.find(end_mark, a)
    assert b >= 0, f"[{label}] 找不到终点：{end_mark[:60]}"
    tail = text[b:] if keep_end else text[b + len(end_mark):]
    return text[:a] + new + tail


