def main():
    s = IDX.read_text(encoding="utf-8")
    before_len = len(s)

    # --- departments.doctor ---
    s = rep(s, DOC_STATUS_OLD, DOC_STATUS_NEW, "doctor.status")
    s = rep(s, DOC_METRIC_ANCHOR, DOC_NEW_METRICS, "doctor.metrics")
    # 尾部本身以 ",nursing:{name:'护理组'" 起头，这里只换掉 advice 数组、不能重复拼一次
    s = cut_between(s, "advice:[['门诊缩量三成，入院反增两成", ",nursing:{name:'护理组'",
                    DOC_ADVICE_NEW, "doctor.advice")

    # --- analytics.doctor ---
    a = s.find("const analytics={doctor:{periods:")
    assert a >= 0
    b = s.find(",nursing:{periods:", a)
    assert b > a
    s = s[:a] + "const analytics={" + DOC_ANALYTICS_NEW + s[b:]

    # --- 静态卡 / 抽屉面板 ---
    s = rep(s, CARD_OLD, CARD_NEW, "DEPT_CARD.note")
    s = rep(s, DD_NOTE_OLD, DD_NOTE_NEW, "deptDaily.note")
    s = rep(s, DD_DIAG_OLD, DD_DIAG_NEW, "deptDaily.diag")

    # --- 首屏三处静态叙述（live-sync 拉不到 /api 时的兜底，必须与线上一致） ---
    s = rep(s, "11.08 22:26 更新 · 汇报表 7 天已填 · 营收日报至 11.06（5 天）· 心理 V4 至 11.08",
            "11.09 09:40 更新 · 汇报表 7 天已填 · 医生周排名已交（7 天 / 7 人）· 营收日报至 11.06（5 天）· 心理 V4 至 11.08",
            "ov-live")
    s = cut_between(s, "<b>⚠ 个人排名本周不可算：</b>", "</p>",
                    "<b>√ 个人周排名已交：</b>《周排名分析》＋《出院结帐明细表》已入库（7 天 / 7 名医生全出数）——"
                    "出院 <b>19</b> 人、在院 <b>26</b> 人（11.08 时点）、个人总业绩 <b>35.66 万</b>、物理 <b>17.71 万</b>、"
                    "心理 <b>1.24 万</b>、本周入院 <b>9</b> 人，排名指数首名 <b>康言 89.9</b>。"
                    "出院 <b>19</b> 人与台账五天 <b>13</b> 人同源互证（11.02—11.06 逐日 0/4/0/1/8 吻合），11.07—11.08 追加 6 人。"
                    "<b>⚠ 结帐表标题标「自费」</b>：入院 <b>9</b> 与汇报表 <b>16</b> 差 <b>7</b> 人，<b>只并列、不互相校验</b>；"
                    "排名指数＝可计分÷<b>65</b>×100，<b>未含质量 20 / 时效 10 / 协作 5</b>，与 10 月月度综合分不可比。",
                    "heroSummary")
    s = rep(s, "医生组＝汇报表表头（<b>58.00 万</b> / 入院 16 / 门诊 181 / 物理 21.0 万）＋营收日报台账（11.02—11.06，5 天）",
            "医生组＝汇报表表头（<b>58.00 万</b> / 入院 16 / 门诊 181 / 物理 21.0 万）＋营收日报台账（11.02—11.06，5 天）"
            "＋出院结帐（7 天：出院 <b>19</b> / 在院 <b>26</b> / 个人业绩 <b>35.66 万</b>，<b>自费口径</b>）",
            "kpi-foot.doctor")
    s = rep(s, "：出院、营销表头、到院登记本周值留空。",
            "：营销表头、到院登记本周值留空（汇报表出院栏仍空，出院改取结帐表 <b>19</b> 人）。",
            "kpi-foot.null")

    # --- 数据核验清单里的医生组条目（原写「个人排名本周不可算」） ---
    s = cut_between(s,
                    "<strong>医生组：表头入院 16、明细 7，个人排名本周不可算</strong>", "</p></div>",
                    "<strong>医生组：表头入院 16、结帐 9，个人排名已交但差 7 人</strong>"
                    "<p>汇报表医生组表头是<b>全组口径</b>（入院 16 / 门诊 181 / 58.0 万）；"
                    "《出院结帐明细表》标「自费」，7 天出院 <b>19</b> 人、在院 <b>26</b> 人、入院 <b>9</b> 人，"
                    "与表头入院 <b>差 7 人</b>——两套口径<b>只并列、不互相校验</b>，需财务书面确认是否只含自费。"
                    "汇报表出院栏仍整格空白、记 null；19 人拆为 11.02—11.06 五天 <b>13</b> 人（与营收台账逐日吻合）"
                    "＋ 11.07—11.08 <b>6</b> 人。<b>排名指数只含 65 分</b>（质量 20 / 时效 10 / 协作 5 未计入），"
                    "且平均床日按最高值归一化、<b>住得越久分越高</b>，两项算法需先定。</p></div>",
                    "quality.doctor")

    # --- 可视化卡「哪些员工现在能公平排名」：医生组由 6/7 变 7/7 ---
    s = rep(s, "31/35<small>数据可用</small>", "31/34<small>数据可用</small>", "viz.signal")
    s = rep(s, '<div class="ring" style="--p:86"><b>6/7</b></div>医生',
            '<div class="ring" style="--p:100"><b>7/7</b></div>医生', "viz.ring.doctor")
    s = cut_between(s, "<b>目前情况：</b>心理 5/5、管家 3/5（国威、菲菲整周无记录）、医生 6/7", "不跨岗合并总分。",
                    "<b>目前情况：</b>心理 5/5、医生 <b>7/7</b>（《周排名分析》＋《出院结帐明细表》已入库，"
                    "排名指数首名康言 89.9）、护士 16/17（<b>任健康整周 0 行</b>，本期已交、六项 94.4%）、"
                    "管家 3/5（国威、菲菲整周无记录）。<b>本周四个岗位都能算个人排名</b>；医生组唯一的缺口是"
                    "结帐表标「自费」，入院 9 与汇报表 16 差 7 人，<b>只并列、不互相校验</b>。"
                    "<br><b>下一步：</b>先书面确认结帐表是否只含自费，再补国威、菲菲的空白，然后谈跨周比较；"
                    "不同岗位仍然分开排名，不跨岗合并总分。",
                    "viz.note")

    IDX.write_text(s, encoding="utf-8")
    print(f"index.html {before_len} → {len(s)} 字符（{len(s) - before_len:+d}）")

    # --- live-sync ---
    l = LIVE.read_text(encoding="utf-8")
    l = rep(l, LS_VAR_OLD, LS_VAR_NEW, "live-sync var")
    l = rep(l, LS_LINE_OLD, LS_LINE_NEW, "live-sync heroSummary")
    LIVE.write_text(l, encoding="utf-8")
    print("live-sync.js 已更新")

    # --- snapshot ---
    snap = json.loads(SNAP.read_text(encoding="utf-8"))
    doc = snap["departments"]["doctor"]

    # 护理完成率此前留空（value=null / due=0），heroSummary 读它 → 补齐
    ntr = snap["metrics"]["nurseTreatRate"]
    ntr.update({"value": 94.4, "due": 691, "done": 652, "missed": 39,
                "status": "ok", "authority": "nursing_weekly"})

    doc["status"] = "周排名已交 · 7 人"
    doc["weekRank"] = SNAP_DOC_RANK
    doc["physioWan"] = 21.0          # 汇报表口径，保留
    doc["rankHead"] = {"name": "康言", "index": 89.9, "revenueWan": 10.79}
    doc["recon"] = {
        "admit": {"header": 16, "detail": 9, "gap": 7, "source": "doctor_week_rank（自费口径）"},
        "discharge": {"header": None, "detail": 19, "gap": None, "source": "doctor_week_rank（自费口径）；11.02—11.06 五天 13 人与营收台账逐日吻合"},
        "note": "汇报表入院 16 人 vs 出院结帐 9 人，差 7 人；结帐表标注「自费」，两者不同源，只并列、不互相校验。",
    }
    snap["watermarks"]["doctor"] = {"dataThrough": "2026-11-08", "days": 7,
                                   "authority": "doctor_week_rank", "selfPay": True}

    srcs = {x["id"]: x for x in snap["sources"]}
    srcs["doctor_week_rank"] = {
        "id": "doctor_week_rank", "name": "医生周排名分析", "url": "local:周排名分析_2026-11-02至11-08.xlsx",
        "enabled": True, "accessVerified": True, "verifyMethod": "业主微信提供（2026-11-09 09:21），本地 openpyxl 读取 3 张 sheet",
        "status": "ok", "dataThrough": "2026-11-08", "lastSuccessAt": "2026-11-09T09:40:00+08:00",
        "note": "7 名医生：个人总业绩 356,593.55 / 物理 177,090 / 心理 12,350 / 出院 19 / 在院 26 / 本周入院 9；排名指数按可计分÷65×100，未含质量 20·时效 10·协作 5",
    }
    srcs["doctor_discharge_ledger"] = {
        "id": "doctor_discharge_ledger", "name": "出院结帐明细表（自费）", "url": "local:重庆梓笙园医院出院结帐明细表_源表对应版_2026-11-08.xlsx",
        "enabled": True, "accessVerified": True, "verifyMethod": "业主微信提供（2026-11-09 09:21），本地 openpyxl 读取 54 行",
        "status": "ok", "dataThrough": "2026-11-08", "lastSuccessAt": "2026-11-09T09:40:00+08:00",
        "note": "出院 21 例（11-01 至 11-08），剔除 11-01 两例后 19 例；标题标「自费」，医保出院可能不在表内",
    }
    snap["sources"] = list(srcs.values())

    snap["revision"] = int(snap.get("revision", 67)) + 1
    tmp = {k: v for k, v in snap.items() if k not in ("generatedAt", "revisionCreatedAt", "_fp")}
    tmp["metrics"] = {mid: {k: v for k, v in mv.items() if k != "publishedAt"}
                      for mid, mv in snap.get("metrics", {}).items()}
    snap["_fp"] = hashlib.sha256(json.dumps(tmp, ensure_ascii=False, sort_keys=True).encode()).hexdigest()
    SNAP.write_text(json.dumps(snap, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(f"snapshot.json revision {snap['revision']} · _fp {snap['_fp'][:12]}")


if __name__ == "__main__":
    main()
